// <auto-generated />
export type LocalValue = { readonly kind: string; readonly value?: unknown; readonly name?: string; readonly items?: ReadonlyArray<LocalValue>; readonly fields?: Readonly<Record<string, LocalValue>> };
export interface LocalSelection {
  readonly name?: string;
  readonly responseName?: string;
  readonly parentType: string;
  readonly local?: boolean;
  readonly typeCondition?: string;
  readonly possibleTypes?: ReadonlyArray<string>;
  readonly argumentDefaults?: Readonly<Record<string, LocalValue>>;
  readonly arguments?: Readonly<Record<string, LocalValue>>;
  readonly include?: ReadonlyArray<LocalValue>;
  readonly skip?: ReadonlyArray<LocalValue>;
  readonly children?: ReadonlyArray<LocalSelection>;
}
export type ResolverFunction<TContext> = (parent: Readonly<Record<string, unknown>>, args: Readonly<Record<string, unknown>>, context: TContext) => unknown | Promise<unknown>;
export type ResolverMap<TContext> = Readonly<Record<string, Readonly<Record<string, ResolverFunction<TContext>>>>>;

export function localValue(input: LocalValue, variables: Readonly<Record<string, unknown>>): unknown {
  switch (input.kind) {
    case 'variable': return variables[input.name!];
    case 'list': return input.items!.map(item => localValue(item, variables));
    case 'object': return Object.fromEntries(Object.entries(input.fields!).map(([key, item]) => [key, localValue(item, variables)]));
    default: return input.value;
  }
}

/** Resolves a generated local selection plan without mutating server response objects. */
export async function resolveLocalSelections<TContext>(data: unknown, selections: ReadonlyArray<LocalSelection>,
  variables: Readonly<Record<string, unknown>>, resolvers: ResolverMap<TContext>, context: TContext): Promise<unknown> {
  if (data === null || data === undefined) return data;
  if (Array.isArray(data)) return Promise.all(data.map(item => resolveLocalSelections(item, selections, variables, resolvers, context)));
  if (typeof data !== 'object') throw new Error('Local selection requires an object response');
  const parent = data as Readonly<Record<string, unknown>>;
  const output: Record<string, unknown> = { ...parent };
  for (const selection of selections) {
    if (selection.include?.some(condition => localValue(condition, variables) !== true) || selection.skip?.some(condition => localValue(condition, variables) === true)) continue;
    if (selection.typeCondition && (parent.__typename ?? selection.parentType) !== selection.typeCondition && !selection.possibleTypes?.includes(String(parent.__typename ?? selection.parentType))) continue;
    if (!selection.name) {
      const nested = await resolveLocalSelections(output, selection.children ?? [], variables, resolvers, context) as Record<string, unknown>;
      for (const [key, item] of Object.entries(nested)) Object.defineProperty(output, key, { value: item, writable: true, enumerable: true, configurable: true });
      continue;
    }
    const responseName = selection.responseName ?? selection.name;
    let result = Object.hasOwn(output, responseName) ? output[responseName] : output[selection.name];
    if (selection.local) {
      const typeName = typeof parent.__typename === 'string' ? parent.__typename : selection.parentType;
      const lookup = (type: string): ResolverFunction<TContext> | undefined => {
        if (!Object.hasOwn(resolvers, type)) return undefined;
        const fields = resolvers[type];
        return fields && Object.hasOwn(fields, selection.name!) ? fields[selection.name!] : undefined;
      };
      const resolver = lookup(typeName) ?? lookup(selection.parentType);
      if (!resolver) throw new Error(`Missing local resolver ${typeName}.${selection.name}`);
      const args = Object.fromEntries(Object.entries(selection.arguments ?? {}).map(([key, input]) => [key, localValue(input, variables)]));
      for (const [key, input] of Object.entries(selection.argumentDefaults ?? {}))
        if (args[key] === undefined) args[key] = localValue(input, variables);
      for (const key of Object.keys(args)) if (args[key] === undefined) delete args[key];
      result = await resolver(output, args, context);
    }
    if (selection.children?.length && result !== null && result !== undefined)
      result = await resolveLocalSelections(result, selection.children, variables, resolvers, context);
    Object.defineProperty(output, responseName, { value: result, writable: true, enumerable: true, configurable: true });
  }
  return output;
}
